BEGIN;
CREATE TABLE app.purchase_order_draft(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,requirement_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id)REFERENCES app.job(tenant_id,id),FOREIGN KEY(tenant_id,requirement_id)REFERENCES app.material_requirement(tenant_id,id));
CREATE TABLE app.purchase_order_revision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,draft_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),quantity_decimal varchar(40) NOT NULL,unit_price_pence bigint NOT NULL CHECK(unit_price_pence>=0 AND unit_price_pence<=1000000000000),order_net_pence bigint NOT NULL CHECK(order_net_pence>=0 AND order_net_pence<=1000000000000),agreed_net_pence bigint NOT NULL CHECK(agreed_net_pence>=0 AND agreed_net_pence<=1000000000000),recipient varchar(320) NOT NULL CHECK(recipient LIKE '%.invalid'),required_date date NOT NULL,authority_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,draft_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,draft_id)REFERENCES app.purchase_order_draft(tenant_id,job_id,id));
CREATE TABLE app.purchase_order_placement(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,draft_id uuid NOT NULL,revision_id uuid NOT NULL,authorization_id uuid NOT NULL,outbox_action_id uuid NOT NULL,command_id uuid NOT NULL,status varchar(40) NOT NULL CHECK(status='simulated'),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,draft_id),UNIQUE(tenant_id,outbox_action_id),FOREIGN KEY(tenant_id,job_id,draft_id)REFERENCES app.purchase_order_draft(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,revision_id)REFERENCES app.purchase_order_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,authorization_id)REFERENCES app.action_authorization(tenant_id,id),FOREIGN KEY(tenant_id,outbox_action_id)REFERENCES app.action_outbox(tenant_id,id),FOREIGN KEY(tenant_id,command_id)REFERENCES app.command_receipt(tenant_id,command_id));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['purchase_order_draft','purchase_order_revision','purchase_order_placement'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
COMMIT;
